// The tools a project can list, each with its logo. Ram picks from this list in the console; projects store the ids.
// To add a tool, add an entry here (a code change, on purpose: the logos are static content). See docs/portfolio.md#stack
//
// Logos are the single-path, 24x24 marks from Simple Icons (https://simpleicons.org, CC0), drawn in their brand
// colour. `color: null` marks a brand colour too dark to read on the dark ground (contrast under 2.5:1 on `surface`);
// those draw in the text colour instead. A tool without a `path` shows a monogram.

export const stackGroups = ['language', 'frontend', 'styling', 'backend', 'data', 'platform', 'service', 'tooling'] as const
export type StackGroup = (typeof stackGroups)[number]

export type StackTool = {
  id: string
  name: string
  group: StackGroup
  /** Brand colour, or null to use the text colour. */
  color?: string | null
  /** SVG path data on a 24x24 viewBox. */
  path?: string
}

